import re, sys

TIME = re.compile(r'([T \t\n\x0b\x0c\r])?([01]?[0-9]|2[0-3]):([0-5][0-9]):([0-5][0-9])([.,:])?([0-9]+)?(Z)?')
DATE = re.compile(
    r'((?:19|20)[0-9]{2})([-/])(0[1-9]|[12][0-9]|3[01])([-/])(0[1-9]|[12][0-9]|3[01])'
    r'|'
    r'(0[1-9]|[12][0-9]|3[01])([-/])(0[1-9]|[12][0-9]|3[01])([-/])((?:19|20)[0-9]{2})'
)
E="\x1b"
def c(code,s): return "%s[%sm%s%s[0m"%(E,code,s,E) if s else ""

def time_repl(m):
    pre,h,mi,s,fsep,frac,z = m.groups()
    return (c(31,pre)+c(34,h)+c(2,':')+c(34,mi)+c(2,':')+c(34,s)
            +c(2,fsep)+c(34,frac)+c(31,z))

def date_repl(m):
    g=m.groups()
    if g[0] is not None:
        y,s1,a,s2,b = g[0],g[1],g[2],g[3],g[4]
    else:
        a,s1,b,s2,y = g[5],g[6],g[7],g[8],g[9]
    return c(35,y)+c(2,s1)+c(35,a)+c(2,s2)+c(35,b)

def apply_layered(line):
    # segments: list of (text, is_highlighted)
    segs=[(line,False)]
    for rx,repl in ((TIME,time_repl),(DATE,date_repl)):
        new=[]
        for text,hl in segs:
            if hl:
                new.append((text,hl)); continue
            pos=0
            for m in rx.finditer(text):
                if m.start()>pos: new.append((text[pos:m.start()],False))
                new.append((repl(m),True))
                pos=m.end()
            if pos<len(text): new.append((text[pos:],False))
        segs=new
    return "".join(t for t,_ in segs)

for line in sys.stdin.read().split("\n"):
    print(apply_layered(line))
PYEOF
